<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();$oldType=(string)($_GET['type']??$_POST['old_type']??'');$oldMin=post_int('old_min')?:filter_var($_GET['min']??0,FILTER_VALIDATE_INT);$oldMax=post_int('old_max')?:filter_var($_GET['max']??0,FILTER_VALIDATE_INT);$types=$pdo->query('SELECT * FROM room_type ORDER BY room_type')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=post('room_type');$min=post_int('min_id');$max=post_int('max_id');if($min<1||$max<$min){flash('error',"Range is not valid [$min, $max].");}else{$s=$pdo->prepare('SELECT COUNT(*) FROM room WHERE room_id BETWEEN ? AND ?'.($oldMin?' AND NOT (room_id BETWEEN ? AND ?)':'') );$params=$oldMin?[$min,$max,$oldMin,$oldMax]:[$min,$max];$s->execute($params);if((int)$s->fetchColumn()>0){flash('error',"Range is not available [$min, $max].");}else{if($oldMin)$pdo->prepare('DELETE FROM room WHERE room_id BETWEEN ? AND ?')->execute([$oldMin,$oldMax]);$ins=$pdo->prepare('INSERT INTO room(room_id,room_type) VALUES(?,?)');for($i=$min;$i<=$max;$i++)$ins->execute([$i,$type]);flash('success','Room range saved.');redirect('rooms.php');}}}
page_header($oldMin?'Edit Rooms':'Add Rooms','room');?>
<div class="page-head"><h1><?=$oldMin?'Edit':'Add'?> Rooms</h1><a class="btn" href="rooms.php">Back</a></div><form class="card form-grid" method="post"><?=csrf_field()?><input type="hidden" name="old_type" value="<?=e($oldType)?>"><input type="hidden" name="old_min" value="<?=$oldMin?>"><input type="hidden" name="old_max" value="<?=$oldMax?>"><label>Room Type<select name="room_type" required><?php foreach($types as $t):?><option value="<?=e($t['room_type'])?>" <?=$oldType===$t['room_type']?'selected':''?>><?=e($t['room_type'])?></option><?php endforeach;?></select></label><label>ID range start<input type="number" min="1" name="min_id" value="<?=$oldMin?:''?>" required></label><label>ID range end<input type="number" min="1" name="max_id" value="<?=$oldMax?:''?>" required></label><div class="full"><button class="btn primary">Save Room Range</button></div></form><?php page_footer();?>
